import React, { useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { getName } from "../redux/actions/index";
import styles from "../styles/search.css";
import { useHistory } from "react-router-dom";

export default function SearchBar() {
  const dispatch = useDispatch();
  const history = useHistory();
  const [name, setName] = useState("");

  function handleInputChange(e) {
    setName(e.target.value);
  }

  function handleSubmit(e) {
    e.preventDefault();
    if (name) {
      dispatch(getName(name));
      setName("");
    }
  }
  
 const dogData = useSelector((state) => state.dogData);

function handleKeyDown(e) {
  if (e.keyCode === 32) {
    handleSubmit(e);
  }
}

return (
  <div>
    <form onSubmit={handleSubmit}>
      <input
        className={styles.searchInput}
        type="text"
        placeholder="Busca Perritos"
        value={name}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
      />
      <button className={styles.lupita} type="submit">
        🔍
      </button>
    </form>
    {dogData && dogData.id && ( // Verificar que hay un perro seleccionado
      history.push(`/dogs:${dogData.id}`) // Redirigir a la página correcta
    )}
  </div>
)}
